using System;using System.Collections.Generic;
namespace UnityEngine {
 internal struct Vector3 {public float x,y,z;internal Vector3(float a,float b,float c){x=a;y=b;z=c;}internal float sqrMagnitude{get{return x*x+y*y+z*z;}}internal Vector3 normalized{get{return this;}}internal static Vector3 up{get{return new Vector3(0,1,0);}}public static Vector3 operator -(Vector3 a,Vector3 b){return new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);}public static Vector3 operator +(Vector3 a,Vector3 b){return new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);}public static Vector3 operator *(Vector3 a,float b){return new Vector3(a.x*b,a.y*b,a.z*b);}}
 internal sealed class Transform {internal Vector3 position;}
 internal static class Mathf {internal static int CeilToInt(float n){return (int)Math.Ceiling(n);}}
 internal static class Random {internal static Vector3 insideUnitSphere{get{return new Vector3(1,0,0);}}}
 internal static class Debug {internal static void LogWarning(string text){}}
}
