internal sealed class DuckovItemAgent {}
internal sealed class CharacterMainControl {internal static CharacterMainControl Main;internal ItemStatsSystem.Item CharacterItem=new ItemStatsSystem.Item {Inventory=new ItemStatsSystem.Inventory()};internal List<ItemStatsSystem.Item> Inventory{get{return CharacterItem.Inventory.Content;}}internal readonly Health Health=new Health();internal readonly UnityEngine.Transform transform=new UnityEngine.Transform();internal BossRush.Teams Team=BossRush.Teams.wolf;internal int InstanceId;internal int GetInstanceID(){return InstanceId;}internal void SetTeam(BossRush.Teams t){Team=t;}}
internal static class PlayerStorageBuffer {internal static readonly List<ItemStatsSystem.Data.ItemTreeData> Buffer=new List<ItemStatsSystem.Data.ItemTreeData>();internal static bool SaveAvailable=true;internal static int Saves;internal static void SaveBuffer(){Saves++;if(!SaveAvailable)throw new Exception("save failure");}}
namespace ItemStatsSystem.Data {internal sealed class ItemTreeData {internal int TypeID;public int rootInstanceID;public int RootTypeID{get{return TypeID;}}internal static ItemTreeData FromItem(ItemStatsSystem.Item item){return new ItemTreeData {TypeID=item.TypeID,rootInstanceID=item.Id};}}}
namespace ItemStatsSystem {
 internal sealed class Item {private static int serial;internal readonly int Id=++serial;internal int TypeID;internal int StackCount=1,MaxStackCount=20;internal bool Stackable=true,Destroyed;internal bool IsBeingDestroyed{get{return Destroyed;}}internal Inventory InInventory,Inventory;internal object PluggedIntoSlot;internal DuckovItemAgent ActiveAgent;internal AgentUtilities AgentUtilities{get{return new AgentUtilities {ActiveAgent=ActiveAgent};}}internal static bool RejectDrop,ThrowDrop,ThrowCombine;internal static int Drops,Destroys;internal void Detach(){if(InInventory!=null)InInventory.Content.Remove(this);InInventory=null;}internal void DestroyTree(){Destroyed=true;Destroys++;}internal void SetInt(string key,int n,bool notify){StackCount=n;}internal void Combine(Item source){int n=Math.Min(MaxStackCount-StackCount,source.StackCount);StackCount+=n;if(ThrowCombine)throw new Exception("combine target notified before source debit");source.StackCount-=n;}internal DuckovItemAgent Drop(UnityEngine.Vector3 p,bool b,UnityEngine.Vector3 d,float force){if(RejectDrop)return null;ActiveAgent=new DuckovItemAgent();Drops++;if(ThrowDrop)throw new Exception("drop notification");return ActiveAgent;}}
 internal sealed class AgentUtilities {internal DuckovItemAgent ActiveAgent;}
 internal sealed class Inventory {internal readonly List<Item> Content=new List<Item>();internal bool Reject,ThrowAfterAdd;internal bool AddItem(Item item){if(Reject)return false;Content.Add(item);item.InInventory=this;if(ThrowAfterAdd)throw new Exception("inventory notification after ownership commit");return true;}}
 internal static class ItemAssetsCollection {internal static bool Available=true;internal static Action FactoryAction;internal static Item InstantiateSync(int type){if(FactoryAction!=null)FactoryAction();return Available?new Item {TypeID=type}:null;}}
}
